(function(){'use strict';
const esc=v=>window.CAGE_ADMISSIONS_COMMON.esc(v??''),api=()=>window.CAGE_BACKEND;
let application,records,training,step=0,busy=false,epoch=0,drafts={};
const titles=['Application & identity','Verify payment','Choose cohort','Confirm enrolment'];
const button=(action,text,id='')=>`<button type="button" class="secondary-button" data-review-action="${action}" data-key="${esc(id)}">${text}</button>`;
const field=(name,label,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const options=(name,label,values,value)=>`<label class="field"><span>${label}</span><select name="${name}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
const note=(name,label,value='')=>`<label class="field"><span>${label}</span><textarea name="${name}" maxlength="10000">${esc(value)}</textarea></label>`;
const files=()=>records.files.filter(f=>f.application_id===application.id);
const money=v=>`${esc(application.form_snapshot.currency)} ${Number(v).toLocaleString()}`;
function balance(){const fee=Number(application.form_snapshot.fee||0),paid=files().filter(f=>f.kind==='payment'&&f.review_status==='Verified').reduce((n,f)=>n+Number(f.amount||0),0);return {fee,paid,left:Math.max(0,fee-paid)};}
const person=id=>training.staff.find(p=>p.id===id)?.full_name||id||'Unknown member';
const stamp=(id,time)=>id?`Saved by ${esc(person(id))} · ${esc(time?new Date(time).toLocaleString():'')}`:'Not verified';
const matching=()=>training.cohorts.filter(c=>!['Completed','Cancelled'].includes(c.status)&&training.courses.some(t=>t.id===c.course_id&&(t.category===application.category||(application.category==='Industry Specific'&&['Technical','Corporate','Other'].includes(t.category)))));
function cohortDetails(id){const c=training.cohorts.find(c=>c.id===id);if(!c)return '<p>Select a cohort.</p>';const count=training.learners.filter(l=>l.cohort_id===id&&!['Withdrawn','Cancelled'].includes(l.stage)).length;return `<div class="academy-review-cohort"><strong>${esc(c.name)}</strong><p>${esc(c.start_date)} – ${esc(c.end_date)} · ${esc(c.venue||'Venue not set')}</p><p>Lead instructor: ${esc(c.lead_instructor?person(c.lead_instructor):'Not assigned')}</p><p>${count} learners · capacity ${esc(c.capacity)}. Availability is checked again on enrolment.</p></div>`;}
function checks(){const a=application,b=balance(),identity=files().filter(f=>f.kind==='identity').sort((a,b)=>b.created_at.localeCompare(a.created_at)||b.id.localeCompare(a.id))[0],draft=a.enrolment_draft||{},today=new Date(Date.now()+7200000).toISOString().slice(0,10);return [
 [a.status==='Accepted','Application accepted'],[!!a.information_verified_by,'Application information verified'],[identity?identity.review_status==='Verified':a.category==='STEM','Identity document verified (optional if absent for STEM)'],[b.fee===0||b.paid>0,'Required deposit verified'],[!b.left||!!draft.balance_due_on&&draft.balance_due_on>=today,'Balance date agreed when required'],[matching().some(c=>c.id===a.planned_cohort_id),'Active matching cohort saved'],[!!draft.full_name&&!!draft.phone&&!!draft.email,'Learner contact details saved'],[a.category!=='STEM'||!!draft.guardian_name&&!!draft.guardian_phone&&draft.guardian_consent===true,'Guardian details and consent, where required']];}
function proof(f,identity=false){return `<article class="academy-review-evidence"><strong>${esc(f.file_name)}</strong><p>${identity?'Identity':money(f.amount)+' · '+esc(f.payment_date)+' · '+esc(f.payment_reference)}</p>${button('file','Open document',f.id)}<p>${esc(f.review_status)} · ${stamp(f.reviewed_by,f.reviewed_at)}</p><form data-review-form="${identity?'identity':'payment'}" data-file="${esc(f.id)}">${options('status','Evidence decision',['Pending','Verified','Rejected'],f.review_status)}${note('note','Note visible to applicant',f.review_note)}<button class="secondary-button">Save evidence decision</button></form></article>`;}
function body(){const a=application,b=balance(),draft=a.enrolment_draft||{};
 if(a.learner_id&&step===3)return `<h2>Learner enrolled</h2><p>This application is linked to learner ${esc(a.learner_id)}.</p>${cohortDetails(a.cohort_id)}<p id="academy-review-email" role="status">Welcome email: ${esc((records.emails||[]).find(e=>e.application_id===a.id)?.status||'Status unavailable')}</p>${button('email','Check welcome email status')}<p>Emails marked sent have been accepted by the provider.</p>${b.left?`<button type="button" class="primary-button" data-ad="reminder" data-id="${esc(a.id)}">Send payment reminder</button>`:''}<button type="button" class="secondary-button" data-ad="reminder-status" data-id="${esc(a.id)}">Check payment reminders</button><div id="ad-reminder-history"></div>`;
 if(step===0)return `<h2>Review application & identity</h2><details open><summary>Submitted answers</summary>${(a.form_snapshot.fields||[]).map(f=>`<div class="stem-answer"><strong>${esc(f.label)}</strong><p>${esc(typeof a.answers[f.id]==='boolean'?(a.answers[f.id]?'Yes':'No'):a.answers[f.id]||'—')}</p></div>`).join('')}</details><h3>Identity evidence</h3>${files().filter(f=>f.kind==='identity').sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(f=>proof(f,true)).join('')||'<p>No identity document uploaded. Optional for STEM.</p>'}${a.learner_id?`<section><h3>Saved application review</h3><p>Status: Enrolled</p><p>${stamp(a.information_verified_by,a.information_verified_at)}</p><h3>Internal staff notes</h3><p class="academy-notes">${esc(a.staff_notes||'No notes recorded.')}</p><p>The enrolment is complete. Identity evidence can still be opened and reviewed above.</p></section>`:`<form data-review-form="decision">${options('status','Application decision',['New','Under review','Needs correction','Accepted','Waitlisted','Declined'],a.status)}<label class="cage-academy-check"><input type="checkbox" name="information" ${a.information_verified_by?'checked':''}>I checked the submitted information</label><p>${stamp(a.information_verified_by,a.information_verified_at)}</p>${note('correction','Corrections requested — visible on the applicant’s private return page',a.correction_note)}<p>A correction request is shown on the private return page. It does not send a notification email.</p>${note('note','Internal staff notes',a.staff_notes)}<button class="primary-button">Save application decision</button></form>`}`;
 if(step===1)return `<h2>Verify payment</h2><p>Verify money received independently before marking evidence Verified. Proof reviews do not create Finance ledger entries.</p>${files().filter(f=>f.kind==='payment').map(f=>proof(f)).join('')||'<p>No payment evidence uploaded.</p>'}<p>${b.fee===0?'This course is free.':b.paid>0?'A verified deposit meets the payment requirement for enrolment.':'A paid course needs a positive verified payment before enrolment.'}</p>`;
 if(step===2&&a.learner_id){const learner=training.learners.find(l=>l.id===a.learner_id),saved=learner||{...a.answers,...draft,full_name:a.full_name,email:a.email,phone:a.phone};return `<h2>Enrolled learner & cohort</h2>${cohortDetails(learner?.cohort_id||a.cohort_id)}${!learner?'<p>The linked learner details could not be loaded. Application details are shown below.</p>':''}<div class="form-grid">${field('saved_full_name','Learner name',saved.full_name,'text','readonly')}${field('saved_email','Contact email',saved.email,'text','readonly')}${field('saved_phone','Contact phone',saved.phone,'text','readonly')}${field('saved_dob','Date of birth',saved.date_of_birth,'text','readonly')}${field('saved_guardian','Guardian name',saved.guardian_name,'text','readonly')}${field('saved_guardian_phone','Guardian phone',saved.guardian_phone,'text','readonly')}</div><p>Guardian consent: ${saved.guardian_consent?'Recorded':'Not recorded'}</p><p>Balance payment date: ${esc(a.balance_due_on||'Not set')}</p>${button('learner','Open learner record')}<p>Use the learner record to update enrolled learner details.</p>`;}
 if(step===2)return `<h2>Choose cohort & learner details</h2><p>Save this plan before confirming enrolment. Saving does not reserve a seat.</p><form data-review-form="cohort"><label class="field"><span>Cohort</span><select name="cohort" required><option value="">Choose a cohort…</option>${matching().map(c=>`<option value="${esc(c.id)}" ${a.planned_cohort_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div id="academy-review-cohort-detail">${cohortDetails(a.planned_cohort_id)}</div><div class="form-grid">${field('full_name','Learner name',draft.full_name??a.full_name,'text','required')}${field('email','Contact email',draft.email??a.email,'email','required')}${field('phone','Contact phone',draft.phone??a.phone,'text','required')}${field('date_of_birth','Date of birth',draft.date_of_birth??a.answers.date_of_birth,'date')}${field('guardian_name','Guardian name',draft.guardian_name??a.answers.guardian_name,'text',a.category==='STEM'?'required':'')}${field('guardian_phone','Guardian phone',draft.guardian_phone??a.answers.guardian_phone,'text',a.category==='STEM'?'required':'')}<label class="cage-academy-check"><input name="guardian_consent" type="checkbox" ${(draft.guardian_consent??a.answers.guardian_consent)===true?'checked':''} ${a.category==='STEM'?'required':''}>Guardian consent checked</label>${b.left?field('balance_due_on','Agreed date to finish paying',draft.balance_due_on||a.balance_due_on||'','date','required min="'+new Date(Date.now()+7200000).toISOString().slice(0,10)+'"'):''}</div><button class="primary-button">Save cohort & learner details</button></form>`;
 const list=checks();if(Object.keys(drafts).length)list.push([false,'Save or discard edits in earlier steps']);return `<h2>Confirm enrolment</h2><p>These checks reflect saved records. The server rechecks them when you confirm.</p><ul class="academy-review-checks">${list.map(([ok,label])=>`<li><span>${ok?'✓':'○'}</span> ${esc(label)} — ${ok?'Ready':'Needs attention'}</li>`).join('')}</ul>${cohortDetails(a.planned_cohort_id)}<p>Learner: ${esc(draft.full_name)} · ${esc(draft.email)} · ${esc(draft.phone)}</p><p>Balance date: ${esc(draft.balance_due_on||'Not required')}</p><p>Confirming creates the learner record once and queues the welcome email automatically.</p><form data-review-form="enrol"><button class="primary-button" ${list.every(([ok])=>ok)?'':'disabled'}>Confirm enrolment & queue welcome email</button></form>`;
}
function render(){let d=document.getElementById('admission-dialog');if(!d){d=document.createElement('dialog');d.id='admission-dialog';document.body.append(d);}d.className='app-dialog academy-dialog cage-academy-admin-dialog academy-review-dialog';const b=balance();d.innerHTML=`<div class="dialog-heading"><div><small>${esc(application.category)} · ${esc(application.status)}</small><h2>${esc(application.full_name)}</h2></div>${button('close','Close')}</div><form id="academy-review-state" data-record="${esc(application.id)}" data-step="${step}"></form><nav class="academy-review-steps" aria-label="Application review steps">${titles.map((t,i)=>`<button type="button" data-review-action="step" data-key="${i}" aria-current="${step===i?'step':'false'}">${i+1}. ${t}</button>`).join('')}</nav><div class="academy-review-layout"><main>${body()}<p id="ad-admin-error" role="alert" class="form-error"></p><p id="academy-review-saved" role="status"></p><div class="dialog-actions">${step>0?button('step','← Previous',step-1):''}${step<3?button('step','Next →',step+1):''}${button('refresh','Refresh saved review')}</div></main><aside><h3>Application summary</h3><p>${esc(application.form_snapshot.title)}</p><p>${esc(application.email)}<br>${esc(application.phone)}</p><dl><dt>Course fee</dt><dd>${money(b.fee)}</dd><dt>Verified payment</dt><dd>${money(b.paid)}</dd><dt>Balance</dt><dd>${money(b.left)}</dd><dt>Agreed / proposed date</dt><dd>${esc(application.balance_due_on||application.enrolment_draft?.balance_due_on||'Not set')}</dd></dl><p>Member actions are recorded in the Academy activity log.</p></aside></div>`;for(const form of d.querySelectorAll('[data-review-form]')){form.id='academy-review-'+form.dataset.reviewForm+(form.dataset.file?'-'+form.dataset.file:'');const values=drafts[form.dataset.reviewForm+':'+(form.dataset.file||'')];if(values)for(const [key,value] of Object.entries(values)){const el=form.elements.namedItem(key);if(el){if(el.type==='checkbox')el.checked=value==='on';else el.value=value;}}}const marker=document.getElementById('academy-review-state');marker.dataset.drafts=JSON.stringify(drafts);if(Object.keys(drafts).length){document.getElementById('academy-review-saved').textContent='You have unsaved edits. Save them in the relevant step before enrolling.';document.querySelector('.academy-review-layout main .dialog-actions').insertAdjacentHTML('beforeend',button('discard','Discard unsaved review edits'));}if(!d.open)d.showModal();}
async function open(id,next=0,keptDrafts={}){const ticket=++epoch;const [r,t]=await Promise.all([api().admissionData(),api().loadTraining()]);if(ticket!==epoch)return;const a=r.applications.find(a=>a.id===id);if(!a)throw new Error('Application unavailable');records=r;training=t;application=a;drafts=keptDrafts;step=Math.max(0,Math.min(3,next));render();}
function report(e){const p=document.getElementById('ad-admin-error');if(p)p.textContent=e.message||String(e);}
function remember(e){const f=e.target.closest('[data-review-form]');if(!f||f.dataset.reviewForm==='enrol')return;const values=Object.fromEntries(new FormData(f));for(const el of f.querySelectorAll('input[type=checkbox]'))if(!el.checked)values[el.name]='';drafts[f.dataset.reviewForm+':'+(f.dataset.file||'')]=values;document.getElementById('academy-review-state').dataset.drafts=JSON.stringify(drafts);}
document.addEventListener('input',remember);
document.addEventListener('change',remember);
document.addEventListener('change',e=>{if(e.target.closest('[data-review-form="cohort"]')&&e.target.name==='cohort')document.getElementById('academy-review-cohort-detail').innerHTML=cohortDetails(e.target.value);});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-review-action]');if(!b||busy)return;try{const action=b.dataset.reviewAction;if(action==='close'){++epoch;document.getElementById('admission-dialog').close();return;}if(action==='step'){step=Number(b.dataset.key);render();}if(action==='discard'){drafts={};render();}if(action==='refresh')await open(application.id,step,drafts);if(action==='file'){b.disabled=true;const url=await api().admissionFile(b.dataset.key);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();}if(action==='learner'){await window.CAGE_ACADEMY.restore({forms:[],origin:{attrs:[['data-academy','learner'],['data-id',application.learner_id]]}});document.getElementById('admission-dialog').close();return;}if(action==='email'){b.disabled=true;const r=await api().admissionEmailStatus(application.id);document.getElementById('academy-review-email').textContent='Welcome email: '+r.status;}}catch(e){report(e);}finally{b.disabled=false;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.reviewForm)return;e.preventDefault();if(busy)return;busy=true;const controls=[...document.querySelectorAll('#admission-dialog button')];controls.forEach(b=>b.disabled=true);try{const v=Object.fromEntries(new FormData(f)),action=f.dataset.reviewForm;
 if(action==='decision')await api().admissionReviewStep({app:application.id,expected_version:application.review_version,new_status:v.status,note:v.note,information_checked:v.information==='on',correction:v.correction});
 if(action==='identity')await api().admissionIdentity(f.dataset.file,v.status,v.note);
 if(action==='payment')await api().admissionPayment(f.dataset.file,v.status,v.note);
 if(action==='cohort'){const {cohort,...details}=v;details.guardian_consent=v.guardian_consent==='on';await api().admissionCohortPlan({app:application.id,expected_version:application.review_version,cohort_key:cohort,details});}
 if(action==='enrol')await api().admissionEnrol(application.id,application.planned_cohort_id,{review_version:application.review_version});
 delete drafts[action+':'+(f.dataset.file||'')];await open(application.id,step,drafts);document.getElementById('academy-review-saved').textContent=action==='enrol'?'Learner enrolled. Welcome email queued.':'Decision saved.';await window.CAGE_ADMISSIONS.reload();
 }catch(e){report(e);}finally{busy=false;controls.forEach(b=>b.disabled=false);}});
window.CAGE_APPLICATION_REVIEW={open};
})();
